                        mask |= 1 << k
                lines.append(mask)
        lines = list(set(lines))

        dp = [float('inf')] * (1 << n)
        dp[0] = 0
        for mask in range(1 << n):
            if dp[mask] == float('inf'):
                continue
            first = -1
