class Solution {
public:
    int minimumLines(vector<vector<int>>& points) {
        int n = points.size();
        if (n <= 2) return 1;
        vector<int> lines;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int mask = (1 << i) | (1 << j);
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];
                for (int k = 0; k < n; k++) {
                    if ((points[k][1] - points[i][1]) * dx == (points[k][0] - points[i][0]) * dy) {
                        mask |= (1 << k);
                    }
                }
                lines.push_back(mask);
            }
        }
        sort(lines.begin(), lines.end());
        lines.erase(unique(lines.begin(), lines.end()), lines.end());
        int total = 1 << n;
        vector<int> dp(total, 1e9);
        dp[0] = 0;
        for (int mask = 0; mask < total; mask++) {
            if (dp[mask] == 1e9) continue;
            int first = -1;
            for (int i = 0; i < n; i++) {
                if (!((mask >> i) & 1)) {
                    first = i;
                    break;
                }
            }
            if (first == -1) continue;
            dp[mask | (1 << first)] = min(dp[mask | (1 << first)], dp[mask] + 1);
            for (int lm : lines) {
                if ((lm >> first) & 1) {
                    dp[mask | lm] = min(dp[mask | lm], dp[mask] + 1);
                }
            }
        }
        return dp[total - 1];
    }
};

class Solution {
    public int minimumLines(int[][] points) {
        int n = points.length;
        if (n <= 2) return 1;
        Set<Integer> lineSet = new HashSet<>();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int mask = (1 << i) | (1 << j);
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];
                for (int k = 0; k < n; k++) {
                    if ((points[k][1] - points[i][1]) * dx == (points[k][0] - points[i][0]) * dy) {
                        mask |= (1 << k);
                    }
                }
                lineSet.add(mask);
            }
        }
        List<Integer> lines = new ArrayList<>(lineSet);
        int total = 1 << n;
        int[] dp = new int[total];
        Arrays.fill(dp, 1000000);
        dp[0] = 0;
        for (int mask = 0; mask < total; mask++) {
            if (dp[mask] == 1000000) continue;
            int first = -1;
            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 0) {
                    first = i;
                    break;
                }
            }
            if (first == -1) continue;
            dp[mask | (1 << first)] = Math.min(dp[mask | (1 << first)], dp[mask] + 1);
            for (int lm : lines) {
                if (((lm >> first) & 1) == 1) {
                    dp[mask | lm] = Math.min(dp[mask | lm], dp[mask] + 1);
                }
            }
        }
        return dp[total - 1];
    }
}

