    const n = points.length;
    if (n <= 2) return 1;
    const lineSet = new Set();
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            let mask = (1 << i) | (1 << j);
            const dx = points[j][0] - points[i][0];
            const dy = points[j][1] - points[i][1];
            for (let k = 0; k < n; k++) {
                if ((points[k][1] - points[i][1]) * dx === (points[k][0] - points[i][0]) * dy) {
                    mask |= (1 << k);
                }
            }
            lineSet.add(mask);
        }
    }
    const lines = Array.from(lineSet);
    const total = 1 << n;
    const dp = new Int32Array(total).fill(1e9);
    dp[0] = 0;
    for (let mask = 0; mask < total; mask++) {
        if (dp[mask] === 1e9) continue;
        let first = -1;
        for (let i = 0; i < n; i++) {
            if (!((mask >> i) & 1)) {
                first = i;
                break;
            }
        }
        if (first === -1) continue;
        dp[mask | (1 << first)] = Math.min(dp[mask | (1 << first)], dp[mask] + 1);
        for (const lm of lines) {
            if ((lm >> first) & 1) {
                dp[mask | lm] = Math.min(dp[mask | lm], dp[mask] + 1);
            }
        }
    }
    return dp[total - 1];
